":["competency-professionalism","survey-professionalism"],"competencyReviewed":true,"surveyReviewed":true,"pages":[22],"notes":["Conflict management and professional interactions."]},{"identityKey":"youtube:_GgJfqoWrlA","title":"A National Strategy to Promote Clinician Wellbeing","url":"https://www.youtube.com/watch?v=_GgJfqoWrlA","tagIds":["competency-professionalism","survey-educational-content"],"competencyReviewed":true,"surveyReviewed":true,"pages":[22],"notes":["Well-being, distress, or impairment education; confirm specific learning objectives."]},{"identityKey":"youtube:fALZDvzuNww","title":"Unconscious Bias - A Discussion with Dr. Ingrid Philibert","url":"https://www.youtube.com/watch?v=fALZDvzuNww","tagIds":["competency-communication","competency-professionalism","survey-heterogeneous-patient-populations","survey-professionalism"],"competencyReviewed":true,"surveyReviewed":true,"pages":[22],"notes":["Bias awareness; respectful interactions across patient populations."]},{"identityKey":"youtube:X3c4ASbZj3Y","title":"Improving Professionalism through EI Skills","url":"https://www.youtube.com/watch?v=X3c4ASbZj3Y","tagIds":["competency-professionalism","survey-professionalism"],"competencyReviewed":true,"surveyReviewed":true,"pages":[22],"notes":["Conflict management and professional interactions."]},{"identityKey":"youtube:6YMgVMmikdg","title":"Physician Impairment: A Personal Journey","url":"https://www.youtube.com/watch?v=6YMgVMmikdg","tagIds":["competency-professionalism","survey-educational-content"],"competencyReviewed":true,"surveyReviewed":true,"pages":[22],"notes":["Well-being, distress, or impairment education; confirm specific learning objectives."]},{"identityKey":"youtube:XBmc4rDh6Rc","title":"Brave Leadership in a Me-First Society","url":"https://www.youtube.com/watch?v=XBmc4rDh6Rc","tagIds":["competency-communication"],"competencyReviewed":true,"surveyReviewed":false,"pages":[22],"notes":["Leadership/communication relevance is indirect; verify respectful-environment or teamwork content."]},{"identityKey":"youtube:fUlXtXUk2l8","title":"Advocacy 101","url":"https://www.youtube.com/watch?v=fUlXtXUk2l8","tagIds":["competency-professionalism","competency-systems-based-practice"],"competencyReviewed":true,"surveyReviewed":false,"pages":[22],"notes":["No clear survey-item connection from title; retain as competency content or review objectives."]},{"identityKey":"youtube:1Aa1wuqcvZU","title":"Lifestyle Medicine: A New Standard of Care","url":"https://www.youtube.com/watch?v=1Aa1wuqcvZU","tagIds":["competency-medical-knowledge","competency-patient-care"],"competencyReviewed":true,"surveyReviewed":false,"pages":[23],"notes":["No clear survey-item connection from title; retain as competency content or review objectives."]},{"identityKey":"youtube:ix_fExBsJME","title":"1st Annual Barbara Wolf Memorial presentation: The Toll it Takes","url":"https://www.youtube.com/watch?v=ix_fExBsJME","tagIds":["competency-communication","survey-educational-content"],"competencyReviewed":true,"surveyReviewed":true,"pages":[23],"notes":["Well-being, distress, or impairment education; confirm specific learning objectives."]}]$payload$::jsonb)
  LOOP
    SELECT id INTO material_id FROM public.vm_library_materials WHERE identity_key=entry->>'identityKey' FOR UPDATE;
    IF material_id IS NULL THEN RAISE EXCEPTION 'Missing material: %. No assignments committed.', entry->>'title'; END IF;
    FOR tag_id IN SELECT jsonb_array_elements_text(entry->'tagIds') LOOP
      IF NOT EXISTS (SELECT 1 FROM public.vm_library_tags WHERE id=tag_id) THEN
        RAISE EXCEPTION 'Missing category: %. No assignments committed.', tag_id;
      END IF;
      INSERT INTO public.vm_library_material_tags(material_id,tag_id) VALUES(material_id,tag_id) ON CONFLICT DO NOTHING;
    END LOOP;
    source_note := '[Boss PDF 2026-11-03] Pages ' || (SELECT string_agg(value, ', ') FROM jsonb_array_elements_text(entry->'pages'))
      || '. ' || (SELECT string_agg(value, ' ') FROM jsonb_array_elements_text(entry->'notes'));
    UPDATE public.vm_library_materials SET
      competency_reviewed=competency_reviewed OR (entry->>'competencyReviewed')::boolean,
      survey_reviewed=survey_reviewed OR (entry->>'surveyReviewed')::boolean,
      review_notes=CASE WHEN position('[Boss PDF 2026-11-03]' in review_notes)>0 THEN review_notes
        ELSE concat_ws(E'\n',nullif(review_notes,''),source_note) END,
      updated_at=CURRENT_TIMESTAMP
    WHERE id=material_id AND (
      (NOT competency_reviewed AND (entry->>'competencyReviewed')::boolean)
      OR (NOT survey_reviewed AND (entry->>'surveyReviewed')::boolean)
      OR position('[Boss PDF 2026-11-03]' in review_notes)=0);
  END LOOP;
END $mapping$;
COMMIT;
SELECT count(DISTINCT material_id) AS materials_with_categories, count(*) AS category_connections
FROM public.vm_library_material_tags;
